// Узел trie: переходы по буквам и признак конца слова
class TrieNode {
  children = new Map<string, TrieNode>();
  isEnd = false;
}

class WordDictionary {
  private root = new TrieNode();

  addWord(word: string): void {
    // Обычная вставка в trie
    let node = this.root;
    for (const ch of word) {
      if (!node.children.has(ch)) {
        node.children.set(ch, new TrieNode());
      }
      node = node.children.get(ch)!;
    }
    node.isEnd = true;
  }

  search(word: string): boolean {
    // dfs(node, i): можно ли сопоставить суффикс word[i..], начиная с узла node
    const dfs = (node: TrieNode, i: number): boolean => {
      // Шаблон закончился — совпадение, только если здесь кончается слово
      if (i === word.length) return node.isEnd;

      const ch = word[i];
      if (ch === '.') {
        // Точка совпадает с любой буквой — пробуем всех детей
        for (const child of node.children.values()) {
          if (dfs(child, i + 1)) return true;
        }
        return false;
      }

      // Обычная буква — единственный возможный переход
      const next = node.children.get(ch);
      return next !== undefined && dfs(next, i + 1);
    };

    return dfs(this.root, 0);
  }
}

// Время: addWord — O(L); search — O(L) без точек, O(26^k · L) с k точками (k <= 2)
// Память: O(суммарная длина слов) на trie + O(L) на стек рекурсии
